    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 45-year-old immigrant from southern China presents with a 3-month history of a painless left neck mass and a sense of fullness in his left ear. Otoscopy reveals a left middle ear effusion. What is the most likely diagnosis?', '["Nasopharyngeal carcinoma", "Oropharyngeal squamous cell carcinoma", "Acoustic neuroma", "Chronic otitis media", "Branchial cleft cyst"]'::jsonb, 0, 'Adult onset of unilateral serous otitis media is a classic presentation of a nasopharyngeal mass (obstructing the Eustachian tube orifice). Nasopharyngeal carcinoma (NPC) is highly endemic in individuals of southern Chinese descent and frequently presents with cervical lymphadenopathy.'),
    (v_topic_id, 'Which viral infection is strongly and consistently associated with the development of endemic nasopharyngeal carcinoma (NPC)?', '["Human papillomavirus (HPV) type 16", "Epstein-Barr virus (EBV)", "Cytomegalovirus (CMV)", "Hepatitis C virus (HCV)", "Human T-cell lymphotropic virus type 1 (HTLV-1)"]'::jsonb, 1, 'Endemic NPC (World Health Organization type III, undifferentiated non-keratinizing carcinoma) is intimately associated with Epstein-Barr virus (EBV) infection.'),
    (v_topic_id, 'What is the most common anatomic site of origin for nasopharyngeal carcinoma?', '["Torus tubarius", "Fossa of Rosenmüller", "Posterior choanae", "Adenoid pad", "Sphenoid sinus ostium"]'::jsonb, 1, 'The fossa of Rosenmüller (the pharyngeal recess located just posterior to the Eustachian tube opening) is the most common site of origin for NPC.'),
    (v_topic_id, 'Which serum marker is frequently utilized for screening, monitoring response to treatment, and detecting recurrence in patients with nasopharyngeal carcinoma?', '["Squamous cell carcinoma antigen (SCCA)", "Carcinoembryonic antigen (CEA)", "EBV DNA load", "Thyroglobulin", "Calcitonin"]'::jsonb, 2, 'Plasma EBV DNA levels correlate well with tumor burden and are an excellent biomarker for diagnosis, prognostication, and detecting early recurrence of NPC.'),
    (v_topic_id, 'What is the primary, standard-of-care treatment modality for stage II-IV nasopharyngeal carcinoma?', '["Primary surgical resection (nasopharyngectomy)", "Concurrent chemoradiotherapy", "Systemic chemotherapy alone", "Immunotherapy alone", "Palliative care"]'::jsonb, 1, 'NPC is exquisitely radiosensitive. Due to the difficult surgical access and high morbidity of resection in the nasopharynx, definitive radiation therapy (with concurrent chemotherapy for advanced stages) is the treatment of choice.'),
    (v_topic_id, 'A 50-year-old man presents with an asymptomatic, 3-cm cystic mass in the right neck (Level II). He has no history of tobacco or alcohol use. Fine-needle aspiration reveals squamous cell carcinoma. What is the most likely site of the primary tumor?', '["Oral tongue", "Nasopharynx", "Oropharynx (base of tongue or tonsil)", "Larynx", "Thyroid gland"]'::jsonb, 2, 'A cystic squamous cell carcinoma metastasis in the neck of a non-smoking adult, historically misdiagnosed as a "branchial cleft cyst," is highly characteristic of an HPV-positive oropharyngeal primary tumor (tonsil or base of tongue).'),
    (v_topic_id, 'In the evaluation of the patient with the cystic neck metastasis from the previous question, immunohistochemical staining of the biopsy for which marker is standard to determine HPV status?', '["p53", "p16", "Ki-67", "c-Myc", "BRAF"]'::jsonb, 1, 'Overexpression of p16 is a highly sensitive and reliable surrogate immunohistochemical marker for transcriptionally active high-risk HPV (specifically HPV-16) infection in oropharyngeal squamous cell carcinoma.'),
    (v_topic_id, 'Why does high-risk HPV infection lead to the overexpression of p16 in oropharyngeal cancer cells?', '["HPV directly stimulates the p16 gene promoter", "The HPV E7 oncoprotein binds and degrades the retinoblastoma (Rb) protein, removing negative feedback and causing a compensatory rise in p16", "The HPV E6 oncoprotein degrades p53, leading to p16 accumulation", "p16 is a viral protein secreted by HPV", "p16 is a host antibody against HPV"]'::jsonb, 1, 'The viral oncoprotein E7 degrades the tumor suppressor Rb. Because Rb normally inhibits p16 expression, the loss of Rb leads to marked, paradoxical overexpression of p16 (a cyclin-dependent kinase inhibitor).'),
    (v_topic_id, 'How does the prognosis of HPV-positive oropharyngeal squamous cell carcinoma compare to that of traditional, HPV-negative (smoking and alcohol-related) oropharyngeal SCC?', '["Significantly worse prognosis", "Equivalent prognosis", "Significantly better prognosis and treatment response", "Better local control but higher rate of distant metastasis", "Unpredictable prognosis"]'::jsonb, 2, 'Despite frequently presenting with advanced nodal disease, HPV-positive oropharyngeal SCC is highly sensitive to radiation and chemotherapy, resulting in markedly higher overall survival and cure rates compared to HPV-negative disease.'),
    (v_topic_id, 'A 55-year-old male with HPV-positive tonsillar cancer presents with a T1N1M0 tumor. Which of the following is a recognized, standard treatment option designed to minimize long-term swallowing dysfunction (dysphagia) compared to traditional primary chemoradiation?', '["Transoral robotic surgery (TORS) or transoral laser microsurgery (TLM) with concurrent neck dissection", "Total glossectomy", "Mandibular split and radical tonsillectomy", "Systemic chemotherapy alone", "Observation"]'::jsonb, 0, 'TORS and TLM are minimally invasive surgical techniques that allow for resection of early-stage oropharyngeal tumors without splitting the jaw or neck, potentially avoiding or reducing the dose of postoperative radiation and preserving better swallowing function.'),
    (v_topic_id, 'A 65-year-old man presents with a "lump in his throat" feeling, a muffled "hot potato" voice, and unilateral left ear pain (otalgia) for 2 months. Otoscopy of the left ear is completely normal. What is the most likely cause of his ear pain?', '["Eustachian tube dysfunction", "Referred pain from a supraglottic or base of tongue malignancy via cranial nerves IX or X", "Temporomandibular joint (TMJ) disorder", "Occult otitis media", "Impacted cerumen"]'::jsonb, 1, 'Referred otalgia in the setting of a normal ear exam is a classic "red flag" symptom of upper aerodigestive tract malignancy. Pain is referred via the tympanic branch of CN IX (Jacobson''s nerve) or the auricular branch of CN X (Arnold''s nerve).'),
    (v_topic_id, 'A 15-year-old adolescent boy presents with severe, recurrent, unilateral epistaxis and progressive left-sided nasal obstruction. Rhinoscopy reveals a red, lobulated mass filling the posterior nasal cavity. What is the most likely diagnosis?', '["Inverted papilloma", "Antrochoanal polyp", "Juvenile nasopharyngeal angiofibroma (JNA)", "Esthesioneuroblastoma", "Squamous cell carcinoma"]'::jsonb, 2, 'JNA is a benign but locally destructive, highly vascular tumor that occurs almost exclusively in adolescent males, presenting classically with the triad of recurrent epistaxis, nasal obstruction, and a nasopharyngeal mass.'),
    (v_topic_id, 'In the evaluation of the 15-year-old boy suspected of having a Juvenile Nasopharyngeal Angiofibroma, which of the following diagnostic procedures is strictly CONTRAINDICATED in the clinic setting?', '["Nasal endoscopy", "CT scan of the sinuses with contrast", "MRI of the face and neck", "Incisional biopsy of the mass", "Angiography"]'::jsonb, 3, 'In-office biopsy of a suspected JNA is strictly contraindicated because the tumor is extraordinarily vascular and lacks a contractile muscular layer in its vessels; a biopsy can precipitate massive, life-threatening hemorrhage.'),
    (v_topic_id, 'A CT scan with contrast of a patient with a Juvenile Nasopharyngeal Angiofibroma classically demonstrates the "Holman-Miller sign." What does this radiologic sign describe?', '["Erosion of the cribriform plate", "Anterior bowing of the posterior wall of the maxillary sinus", "Widening of the pterygomaxillary fissure", "Opacification of the sphenoid sinus", "Bilateral nasal polyposis"]'::jsonb, 1, 'The Holman-Miller sign is the characteristic anterior bowing of the posterior wall of the maxillary sinus, caused by the JNA pushing forward as it expands outward from the sphenopalatine foramen.'),
    (v_topic_id, 'What is a critical preoperative step routinely performed 24-48 hours before the surgical resection of a Juvenile Nasopharyngeal Angiofibroma to reduce intraoperative bleeding?', '["Administration of high-dose corticosteroids", "Preoperative radiation therapy", "Systemic chemotherapy", "Angiography with embolization of the feeding vessels", "Administration of desmopressin (DDAVP)"]'::jsonb, 3, 'Preoperative selective embolization (usually of branches of the internal maxillary artery) significantly reduces the extreme vascularity of the tumor, making surgical resection safer and reducing blood loss.'),
    (v_topic_id, 'A 55-year-old man presents with unilateral right-sided nasal obstruction and recurrent sinusitis. Endoscopy shows a firm, fleshy, polypoid mass arising from the lateral nasal wall. The pathologist reports "hyperplastic epithelium growing inward into the underlying stroma." What is the diagnosis?', '["Allergic fungal rhinosinusitis", "Inverted papilloma", "Juvenile nasopharyngeal angiofibroma", "Esthesioneuroblastoma", "Nasal squamous cell carcinoma"]'::jsonb, 1, 'Inverted papilloma is a benign, locally aggressive sinonasal tumor characterized by epithelial invagination (inverting) into the stroma. Unlike inflammatory polyps, it is typically unilateral and firmer.'),
    (v_topic_id, 'Why is complete surgical excision with wide margins (often via endoscopic medial maxillectomy) mandatory for an inverted papilloma?', '["To prevent severe bleeding", "Because it invariably causes brain abscesses", "Because it is associated with a 5-10% rate of synchronous or metachronous transformation into squamous cell carcinoma", "Because it spreads to regional lymph nodes rapidly", "To prevent allergic sensitization"]'::jsonb, 2, 'Inverted papillomas have a high recurrence rate if incompletely excised and carry a well-documented risk of malignant transformation into SCC, necessitating complete removal with subperiosteal margins.'),
    (v_topic_id, 'A 45-year-old woman presents with a 6-month history of unilateral right nasal obstruction, recurrent epistaxis, and loss of smell (anosmia). MRI shows a "dumbbell-shaped" mass extending from the superior nasal vault through the cribriform plate into the anterior cranial fossa. What is the most likely diagnosis?', '["Inverted papilloma", "Esthesioneuroblastoma (olfactory neuroblastoma)", "Squamous cell carcinoma", "Juvenile nasopharyngeal angiofibroma", "Meningioma"]'::jsonb, 1, 'Esthesioneuroblastoma is a rare malignant tumor arising from the olfactory neuroepithelium high in the nasal vault, explaining the classic symptom of anosmia and the propensity to invade the cribriform plate.'),
    (v_topic_id, 'What is the classic histopathologic finding in an Esthesioneuroblastoma?', '["Keratin pearls and intercellular bridges", "Small round blue cells forming Homer-Wright rosettes", "Biphasic spindle cells and epithelial cells", "Giant multinucleated cells with eosinophilic inclusions", "Clear cells with abundant lipid"]'::jsonb, 1, 'Esthesioneuroblastoma is a neuroendocrine tumor; histology classically shows a "small round blue cell tumor" pattern with Homer-Wright rosettes and positive immunohistochemical staining for markers like synaptophysin, chromogranin, and neuron-specific enolase (NSE).'),
    (v_topic_id, 'A 70-year-old retired carpenter and furniture maker presents with unilateral nasal obstruction, facial pain, and a feeling that his upper right teeth are becoming loose. CT shows a destructive mass in the right maxillary sinus. His occupational exposure puts him at highest risk for which specific malignancy?', '["Squamous cell carcinoma", "Intestinal-type adenocarcinoma", "Esthesioneuroblastoma", "Melanoma", "Lymphoma"]'::jsonb, 1, 'Occupational exposure to hardwood dust (e.g., in carpenters and furniture makers) is a classic risk factor strongly associated with the development of sinonasal adenocarcinomas, specifically the intestinal-type.'),
    (v_topic_id, 'Which of the following is a defining feature of a Carcinoma of Unknown Primary (CUP) in the head and neck?', '["A tumor found in the lungs with no known head and neck origin", "A patient presents with metastatic squamous cell carcinoma in a cervical lymph node, but complete mucosal examination and imaging reveal no obvious primary tumor", "A parotid mass that cannot be diagnosed by FNA", "A neck mass that disappears after antibiotic therapy", "A skin cancer that has metastasized to the brain"]'::jsonb, 1, 'CUP is defined as the presence of metastatic cancer (typically SCC) in a cervical lymph node without a clinically or radiographically evident primary tumor in the upper aerodigestive tract at presentation.'),
    (v_topic_id, 'In a patient presenting with a Carcinoma of Unknown Primary (squamous cell carcinoma in a Level II neck node), where is the most statistically likely location of the hidden primary tumor?', '["Nasopharynx", "Thyroid gland", "Oropharynx (tonsillar crypts or base of tongue)", "Larynx", "Esophagus"]'::jsonb, 2, 'The lymphoid tissues of Waldeyer''s ring, particularly the deep crypts of the palatine tonsils and the base of the tongue, are notorious for harboring small, occult primary squamous cell carcinomas (often HPV-positive) that present initially as large neck metastases.'),
    (v_topic_id, 'What is the appropriate operative diagnostic procedure for a patient with a suspected Carcinoma of Unknown Primary in the neck after imaging (CT/PET) is negative?', '["Immediate radical neck dissection", "Panendoscopy (direct laryngoscopy, esophagoscopy, bronchoscopy) with directed biopsies and bilateral tonsillectomy", "Blind biopsies of the entire oral cavity", "Observation with repeat imaging in 3 months", "Empiric radiation therapy to the neck only"]'::jsonb, 1, 'A thorough operative evaluation under general anesthesia (panendoscopy) with directed biopsies of high-risk areas (nasopharynx, base of tongue, pyriform sinuses) and bilateral palatine tonsillectomy is the gold standard for finding the hidden primary tumor.'),
    (v_topic_id, 'A 60-year-old man presents with a rapidly growing, exophytic, "cauliflower-like" mass on his hard palate. Biopsy shows pseudoepitheliomatous hyperplasia mimicking squamous cell carcinoma, but the pathologist notes it is a benign, self-limiting condition often caused by localized ischemia (e.g., from a dental injection). What is the diagnosis?', '["Necrotizing sialometaplasia", "Torus palatinus", "Pleomorphic adenoma", "Verrucous carcinoma", "Kaposi sarcoma"]'::jsonb, 0, 'Necrotizing sialometaplasia is a benign inflammatory condition of the minor salivary glands, most commonly on the hard palate, characterized by ischemic necrosis and subsequent squamous metaplasia that can closely mimic malignancy both clinically and histologically.'),
    (v_topic_id, 'A 25-year-old woman presents with a hard, painless, bony swelling in the midline of her hard palate that has been present since her teenage years and has slowly enlarged. The overlying mucosa is normal. What is the most likely diagnosis?', '["Osteosarcoma", "Pleomorphic adenoma", "Torus palatinus", "Ameloblastoma", "Fibrous dysplasia"]'::jsonb, 2, 'Torus palatinus is a common, benign bony exostosis occurring in the midline of the hard palate. It is painless, developmental, and requires no treatment unless it interferes with the fitting of a denture or becomes repeatedly traumatized.'),
    (v_topic_id, 'A 35-year-old man presents with a slow-growing, painless swelling of the posterior mandible. Panoramic radiograph shows a multilocular, radiolucent "soap bubble" appearance. Biopsy confirms an odontogenic tumor. What is the most likely diagnosis?', '["Ameloblastoma", "Odontoma", "Osteosarcoma", "Dentigerous cyst", "Radicular cyst"]'::jsonb, 0, 'Ameloblastoma is the most common clinically significant odontogenic tumor. It typically arises in the posterior mandible and classically presents on radiographs as a multilocular, expansile radiolucency ("soap bubble" or "honeycomb" appearance).'),
    (v_topic_id, 'Why is enucleation or curettage considered inadequate treatment for an ameloblastoma?', '["It is a highly malignant tumor that rapidly metastasizes", "It frequently undergoes spontaneous regression", "It is locally invasive and infiltrates the cancellous bone beyond the radiographic margins, leading to a high recurrence rate if simply scraped out", "It responds better to radiation therapy", "It is impossible to scrape out due to extreme hardness"]'::jsonb, 2, 'Despite being a benign tumor (rarely metastasizing), ameloblastoma is locally aggressive. Simple curettage results in recurrence rates up to 90%. Marginal or segmental mandibular resection with 1-cm bony margins is the standard of care.'),
    (v_topic_id, 'Which odontogenic tumor is considered a hamartoma rather than a true neoplasm and typically presents on x-ray as a dense, radiopaque mass containing multiple small, tooth-like structures?', '["Ameloblastoma", "Odontoma", "Myxoma", "Cementoblastoma", "Keratocystic odontogenic tumor"]'::jsonb, 1, 'An odontoma is a hamartoma composed of enamel, dentin, and cementum. A "compound" odontoma looks like a collection of tiny, malformed teeth, while a "complex" odontoma is a disorganized radiopaque mass.'),
    (v_topic_id, 'A patient presents with a unilocular radiolucency associated with the crown of an unerupted, impacted third molar (wisdom tooth). The cyst attaches to the tooth at the cementoenamel junction. What is the diagnosis?', '["Radicular (periapical) cyst", "Dentigerous (follicular) cyst", "Odontogenic keratocyst", "Ameloblastoma", "Lateral periodontal cyst"]'::jsonb, 1, 'A dentigerous cyst is the most common developmental odontogenic cyst. It originates from the reduced enamel epithelium and surrounds the crown of an unerupted tooth, attaching at the cementoenamel junction.'),
    (v_topic_id, 'Which odontogenic cyst is characterized by a high recurrence rate after enucleation and is a classic feature of Nevoid Basal Cell Carcinoma Syndrome (Gorlin syndrome)?', '["Dentigerous cyst", "Radicular cyst", "Odontogenic keratocyst (OKC)", "Glandular odontogenic cyst", "Nasopalatine duct cyst"]'::jsonb, 2, 'The Odontogenic Keratocyst (OKC) is known for its aggressive behavior, high recurrence rate (due to friable lining and daughter cysts), and strong association with Gorlin syndrome (PTCH1 gene mutation) when presenting as multiple cysts.'),
    (v_topic_id, 'A patient with multiple jaw cysts (odontogenic keratocysts), multiple basal cell carcinomas of the skin at a young age, palmar/plantar pits, and calcification of the falx cerebri has which genetic syndrome?', '["Multiple Endocrine Neoplasia type 2B (MEN 2B)", "Gardner syndrome", "Nevoid Basal Cell Carcinoma Syndrome (Gorlin syndrome)", "Cowden syndrome", "Peutz-Jeghers syndrome"]'::jsonb, 2, 'Gorlin syndrome (Nevoid Basal Cell Carcinoma Syndrome) is an autosomal dominant disorder caused by a mutation in the PTCH1 tumor suppressor gene on chromosome 9q, characterized by this classic pentad of findings.'),
    (v_topic_id, 'A 60-year-old male presents with a rock-hard, fixed mass in the right submandibular triangle and numbness of the right lower lip. What is the significance of the lower lip numbness?', '["It indicates spread to the facial nerve", "It signifies perineural invasion of the mandibular division of the trigeminal nerve (mental/inferior alveolar nerve), strongly suggesting a malignancy like adenoid cystic carcinoma", "It is a sign of a benign pleomorphic adenoma", "It indicates an infection in the floor of the mouth", "It is unrelated to the neck mass"]'::jsonb, 1, 'Cranial neuropathy (such as numbness in the V3 distribution) in the presence of a salivary gland mass is a highly specific sign of malignancy, most notably adenoid cystic carcinoma which is prone to perineural spread.'),
    (v_topic_id, 'What is the most common clinical presentation of a nasopharyngeal angiofibroma?', '["Painless neck mass in an elderly male", "Severe, recurrent epistaxis and nasal obstruction in an adolescent male", "Anosmia and visual loss in a middle-aged female", "Unilateral hearing loss and tinnitus in a young adult", "Facial pain and loose teeth in an older adult"]'::jsonb, 1, 'Juvenile nasopharyngeal angiofibroma (JNA) almost exclusively affects adolescent males and presents with recurrent, severe epistaxis and progressive nasal obstruction.'),
    (v_topic_id, 'In an older adult presenting with a new-onset, unilateral serous otitis media (middle ear effusion), which anatomic area MUST be thoroughly examined to rule out malignancy?', '["The larynx", "The oropharynx", "The nasopharynx", "The hypopharynx", "The thyroid gland"]'::jsonb, 2, 'Unilateral serous otitis media in an adult is a red flag for a nasopharyngeal mass (such as nasopharyngeal carcinoma) obstructing the Eustachian tube. Flexible fiberoptic nasopharyngoscopy is mandatory.'),
    (v_topic_id, 'What is the preferred method for establishing a definitive diagnosis of a suspected nasopharyngeal carcinoma?', '["Open neck biopsy of a lymph node", "Fine-needle aspiration (FNA) of a neck node", "Endoscopic-guided biopsy of the primary nasopharyngeal mass", "Excisional biopsy of the tonsil", "Blind biopsies of the nasopharynx"]'::jsonb, 2, 'While FNA of a neck node can suggest the diagnosis, the definitive diagnosis and staging require an endoscopic-guided biopsy of the primary tumor in the nasopharynx (usually the fossa of Rosenmüller).'),
    (v_topic_id, 'A patient with an early-stage (T1N0) squamous cell carcinoma of the true vocal cord (glottis) opts for radiation therapy. What is the primary advantage of radiation therapy over surgical resection (e.g., endoscopic laser excision) for this patient?', '["Higher cure rate", "Lower risk of distant metastasis", "Better long-term voice quality in some patients, though cure rates are equivalent", "Shorter treatment duration", "No need for post-treatment surveillance"]'::jsonb, 2, 'Both primary radiation and endoscopic laser excision offer >90% cure rates for T1 glottic SCC. Radiation is often chosen by patients who rely heavily on voice quality (e.g., singers, teachers) as it can result in a more normal-sounding voice post-treatment compared to surgical scarring.'),
    (v_topic_id, 'Which subsite of the larynx is associated with the lowest rate of regional lymph node metastasis at the time of diagnosis?', '["Supraglottis", "Glottis (true vocal cords)", "Subglottis", "Pyriform sinus", "Epiglottis"]'::jsonb, 1, 'The glottis (true vocal cords) has sparse lymphatic drainage. Therefore, early glottic cancers (T1, T2) have an extremely low rate of regional nodal metastasis (<5%), unlike the supraglottis or subglottis which have rich lymphatic networks.'),
    (v_topic_id, 'A 65-year-old male smoker presents with a 3-month history of persistent hoarseness. He has no pain or difficulty swallowing. Indirect laryngoscopy reveals a white, exophytic lesion confined to the anterior third of the right true vocal cord. Cord mobility is normal. What is the clinical T stage?', '["T1", "T2", "T3", "T4", "Tis"]'::jsonb, 0, 'A tumor confined to the true vocal cord(s) with normal vocal cord mobility is classified as a T1 glottic carcinoma.'),
    (v_topic_id, 'In the staging of glottic squamous cell carcinoma, what clinical finding upstages the tumor to T3?', '["Extension to the supraglottis", "Extension to the subglottis", "Fixation (paralysis) of the true vocal cord", "Invasion of the thyroid cartilage", "Metastasis to a single ipsilateral lymph node"]'::jsonb, 2, 'Vocal cord fixation (paralysis) indicates deep muscle or paraglottic space invasion and automatically upstages a laryngeal tumor to T3, significantly altering the treatment approach (often requiring chemoradiation or total laryngectomy).'),
    (v_topic_id, 'A 58-year-old alcoholic presents with severe dysphagia, weight loss, and referred left ear pain. Laryngoscopy shows a massive, ulcerated tumor on the laryngeal surface of the epiglottis. He has bilateral firm cervical lymph nodes. What is the primary anatomical reason for the frequent bilateral nodal presentation in this tumor location?', '["The aggressive histological grade", "The rich, crossing bilateral lymphatic drainage network of the supraglottis", "The presence of a patent foramen ovale", "Hematogenous spread", "Direct extension into the neck spaces"]'::jsonb, 1, 'The supraglottis is derived from the embryologic buccopharyngeal primordium and has an extremely rich, bilaterally crossing lymphatic network. As a result, up to 40% of supraglottic tumors present with bilateral neck metastases.'),
    (v_topic_id, 'What is the most emergent and life-threatening complication of a rapidly growing subglottic squamous cell carcinoma?', '["Vocal cord paralysis", "Esophageal obstruction", "Airway obstruction (stridor)", "Carotid artery blowout", "Distant metastasis to the brain"]'::jsonb, 2, 'Subglottic tumors grow in the narrowest part of the pediatric and adult airway (the cricoid ring). As they expand, they cause progressive airway narrowing, eventually presenting as a life-threatening emergency with biphasic stridor.'),
    (v_topic_id, 'Which of the following is a classic symptom of an advanced tumor originating in the pyriform sinus (hypopharynx)?', '["Early hoarseness", "Anosmia", "Progressive dysphagia to solids", "Recurrent epistaxis", "Visual field deficits"]'::jsonb, 2, 'The hypopharynx (including the pyriform sinuses) is part of the swallowing passage. Tumors here often remain clinically silent until they grow large enough to cause obstructive symptoms, typically presenting as progressive dysphagia and weight loss.'),
    (v_topic_id, 'A patient undergoes a total laryngectomy for a T4 glottic carcinoma. Postoperatively, how will the patient breathe?', '["Through their nose and mouth normally", "Through a temporary tracheostomy tube that will be decannulated later", "Through a permanent end tracheostoma in the lower anterior neck", "Through an endotracheal tube", "Through a CPAP machine"]'::jsonb, 2, 'In a total laryngectomy, the entire larynx is removed, and the trachea is brought out to the skin of the lower neck as a permanent, irreversible end tracheostoma. The patient no longer has a connection between the pharynx/mouth and the lungs.'),
    (v_topic_id, 'After a total laryngectomy, patients lose their natural voice. Which of the following is the most common and effective method for voice rehabilitation?', '["Esophageal speech (swallowing air and burping it out)", "Electrolarynx (vibrating device held to the neck)", "Tracheoesophageal puncture (TEP) with a voice prosthesis", "Laryngeal transplantation", "Sign language"]'::jsonb, 2, 'A tracheoesophageal puncture (TEP) creates a small fistula between the posterior tracheal wall and the anterior esophagus. A one-way valve prosthesis is inserted, allowing the patient to shunt pulmonary air into the pharynx to produce fluent, relatively natural-sounding speech.'),
    (v_topic_id, 'Which human papillomavirus (HPV) subtypes are most frequently implicated in the development of Recurrent Respiratory Papillomatosis (RRP) in both children and adults?', '["HPV 16 and 18", "HPV 6 and 11", "HPV 31 and 33", "HPV 2 and 4", "HPV 5 and 8"]'::jsonb, 1, 'RRP is a benign but highly morbid disease characterized by recurrent warty growths on the vocal cords and airway, overwhelmingly caused by the "low-risk" HPV types 6 and 11.'),
    (v_topic_id, 'What is the primary treatment modality for managing the recurrent airway lesions in Recurrent Respiratory Papillomatosis (RRP)?', '["Systemic chemotherapy", "Definitive radiation therapy", "Repeated endoscopic microdebrider or laser ablation", "Total laryngectomy", "Long-term high-dose corticosteroids"]'::jsonb, 2, 'Because the disease is recurrent, the goal is to maintain a safe airway and functional voice. Repeated surgical ablation (using a microdebrider, CO2 laser, or KTP laser) is the mainstay of treatment. Radiation is contraindicated due to the risk of malignant transformation.'),
    (v_topic_id, 'A 40-year-old singer presents with hoarseness after an upper respiratory infection and a bout of aggressive coughing. Laryngoscopy reveals a unilateral, reddish, broad-based swelling on the vibratory margin of the vocal cord. What is the likely diagnosis?', '["Vocal cord nodule", "Vocal cord polyp", "Squamous cell carcinoma", "Laryngeal papilloma", "Reinke''s edema"]'::jsonb, 1, 'Vocal cord polyps are typically unilateral, highly vascular (reddish), and often occur after a single episode of vocal trauma or hemorrhage. In contrast, nodules are typically bilateral, pale, and related to chronic vocal abuse.'),
    (v_topic_id, 'What is the classic laryngoscopic finding in a patient with Reinke''s edema (polypoid corditis)?', '["Bilateral, tiny, pale, pinpoint nodules at the anterior third of the vocal cords", "Unilateral, large, hemorrhagic polyp", "Bilateral, diffuse, massive \"water-balloon-like\" swelling of the entire true vocal cords", "An exophytic, warty growth", "An ulcerated, indurated mass"]'::jsonb, 2, 'Reinke''s edema is characterized by the accumulation of gelatinous fluid in the superficial lamina propria (Reinke''s space), causing massive, bilateral, floppy swelling. It is almost exclusively seen in middle-aged women with a heavy smoking history, causing a classic deep, "gravelly" voice.'),
    (v_topic_id, 'A patient with a history of long-standing endotracheal intubation in the ICU develops progressive shortness of breath weeks after extubation. Laryngoscopy shows a web-like narrowing just below the vocal cords. What is the diagnosis?', '["Bilateral vocal cord paralysis", "Subglottic stenosis", "Laryngeal web", "Laryngomalacia", "Tracheomalacia"]'::jsonb, 1, 'Subglottic stenosis is a common and serious complication of prolonged endotracheal intubation. Pressure from the endotracheal tube cuff causes ischemia, necrosis, and subsequent circumferential scarring of the cricoid ring.'),
    (v_topic_id, 'A patient presents with a slowly growing, very hard mass over the cricoid cartilage. The overlying mucosa is completely normal. CT shows a mass with "popcorn" calcifications expanding the cricoid cartilage. What is the diagnosis?', '["Squamous cell carcinoma", "Chondrosarcoma of the larynx", "Osteosarcoma", "Thyroid anaplastic carcinoma", "Parathyroid adenoma"]'::jsonb, 1, 'Chondrosarcoma is the most common mesenchymal tumor of the larynx, classically arising from the cricoid cartilage. Because it arises within the cartilage, the overlying mucosa is spared until late in the disease. "Popcorn" calcification is a classic radiographic sign.')
